#!/usr/bin/env python3
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-18
"""Check a peer skill installed from another marketplace: installed version
against the version that marketplace publishes. First user: typesafe@typesafe-ai,
the TypeSafe agent skill the Jev routing seam (#4233) builds on.

Reads only local files under the Claude plugins dir (default ~/.claude/plugins):
  known_marketplaces.json                  is the marketplace added, where is its clone
  installed_plugins.json                   is the plugin installed, at which version
  <clone>/.claude-plugin/marketplace.json  the version the marketplace publishes
No network. Fixture tested with --plugins-dir.

Usage: check-peer-skill.py [--plugin NAME@MARKETPLACE] [--plugins-dir PATH] [--json]

Verdicts (one line, or one JSON object with --json):
  MARKETPLACE_MISSING  the marketplace was never added
  REGISTRY_UNREADABLE  a registry file exists but cannot be read or parsed (could not observe)
  PLUGIN_MISSING       marketplace present, plugin not installed
  UPDATE_AVAILABLE     installed version differs from the marketplace version
  UP_TO_DATE           versions match
  VERSION_UNKNOWN      installed, but the marketplace clone publishes no version

Exit codes: 0 = UP_TO_DATE or VERSION_UNKNOWN; 1 = any verdict with a fix; 2 = usage.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

DEFAULT_PLUGIN = "typesafe@typesafe-ai"
OK_VERDICTS = {"UP_TO_DATE", "VERSION_UNKNOWN"}


class RegistryUnreadable(Exception):
    """The registry file exists but cannot be read or parsed."""


def load(path: str | Path) -> dict:
    """Return the registry dict; {} when absent; raise when present but unreadable."""
    p = Path(path)
    if not p.exists():
        return {}
    try:
        with p.open(encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError) as exc:
        raise RegistryUnreadable(f"{p}: {exc}") from exc
    return data if isinstance(data, dict) else {}


def installed_version(installed_file: str | Path, ref: str) -> str:
    plugins = load(installed_file).get("plugins")
    if not isinstance(plugins, dict):
        return ""
    records = plugins.get(ref)
    if isinstance(records, dict):
        records = [records]
    if not isinstance(records, list):
        return ""
    for rec in records:
        if isinstance(rec, dict) and isinstance(rec.get("version"), str):
            return rec["version"]
    return ""


def published_version(market_entry: dict, plugin: str) -> str:
    location = market_entry.get("installLocation")
    if not isinstance(location, str) or not location:
        return ""
    manifest = load(Path(location) / ".claude-plugin" / "marketplace.json")
    for item in manifest.get("plugins") or []:
        if (
            isinstance(item, dict)
            and item.get("name") == plugin
            and isinstance(item.get("version"), str)
        ):
            return item["version"]
    if manifest.get("name") == plugin and isinstance(manifest.get("version"), str):
        return manifest["version"]
    return ""


def resolve(plugins_dir: str, ref: str) -> dict:
    plugin, market = ref.split("@", 1)
    result = {
        "plugin": ref,
        "verdict": "",
        "installed": None,
        "published": None,
        "detail": None,
        "fix": None,
    }
    try:
        markets = load(Path(plugins_dir) / "known_marketplaces.json")
    except RegistryUnreadable as exc:
        result["verdict"] = "REGISTRY_UNREADABLE"
        result["detail"] = str(exc)
        result["fix"] = "repair or remove the unreadable registry file, then rerun"
        return result
    entry = markets.get(market)
    if not isinstance(entry, dict):
        result["verdict"] = "MARKETPLACE_MISSING"
        result["detail"] = f"marketplace {market} not in known_marketplaces.json"
        result["fix"] = (
            f"claude plugin marketplace add {market}/skills && claude plugin install {ref}"
        )
        return result
    try:
        installed = installed_version(Path(plugins_dir) / "installed_plugins.json", ref)
    except RegistryUnreadable as exc:
        result["verdict"] = "REGISTRY_UNREADABLE"
        result["detail"] = str(exc)
        result["fix"] = "repair or remove the unreadable registry file, then rerun"
        return result
    if not installed:
        result["verdict"] = "PLUGIN_MISSING"
        result["detail"] = f"plugin {plugin} not in installed_plugins.json"
        result["fix"] = f"claude plugin install {ref}"
        return result
    result["installed"] = installed
    published = published_version(entry, plugin)
    if not published:
        result["verdict"] = "VERSION_UNKNOWN"
        result["detail"] = f"marketplace clone publishes no version for {plugin}"
        return result
    result["published"] = published
    if published == installed:
        result["verdict"] = "UP_TO_DATE"
        return result
    result["verdict"] = "UPDATE_AVAILABLE"
    result["fix"] = f"claude plugin marketplace update {market} && claude plugin update {ref}"
    return result


def render(r: dict) -> str:
    ref, v = r["plugin"], r["verdict"]
    if v == "UP_TO_DATE":
        return f"{ref}: OK ({r['installed']}, matches marketplace)"
    if v == "VERSION_UNKNOWN":
        return f"{ref}: installed {r['installed']} (marketplace publishes no version)"
    if v == "UPDATE_AVAILABLE":
        return f"{ref}: UPDATE AVAILABLE ({r['installed']} installed, {r['published']} in marketplace). Fix: {r['fix']}"
    if v == "PLUGIN_MISSING":
        return f"{ref}: PLUGIN MISSING ({r['detail']}). Fix: {r['fix']}"
    if v == "REGISTRY_UNREADABLE":
        return f"{ref}: REGISTRY UNREADABLE, could not observe ({r['detail']}). Fix: {r['fix']}"
    return f"{ref}: MARKETPLACE MISSING ({r['detail']}). Fix: {r['fix']}"


def main() -> int:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument(
        "--plugin", default=DEFAULT_PLUGIN, help="NAME@MARKETPLACE (default typesafe@typesafe-ai)"
    )
    parser.add_argument(
        "--plugins-dir", default=Path.home() / ".claude" / "plugins"
    )
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()
    if "@" not in args.plugin:
        print(f"plugin ref must be NAME@MARKETPLACE, got: {args.plugin}", file=sys.stderr)
        return 2
    result = resolve(args.plugins_dir, args.plugin)
    print(json.dumps(result) if args.json else render(result))
    return 0 if result["verdict"] in OK_VERDICTS else 1


if __name__ == "__main__":
    sys.exit(main())
